#!/usr/bin/env python3
"""
Resolves every call to a service or component (CartService, SettlementService, LockRetry, BillMath...)
against the method it calls: its NAME and its NUMBER OF ARGUMENTS.

Written because a signature changed in several places across the table-ordering work, and a wrong
argument count is a compile error that the Java syntax pass cannot show (it filters out "cannot find
symbol" because without dependencies on the classpath every file produces hundreds of them).

*Properties classes are skipped: their getters are generated by Lombok, which this cannot see.
Mutation-tested: changing a call's argument count makes it fail.
"""
import re, sys, pathlib
SRC = pathlib.Path('/home/claude/kashmirmenu/src/main/java')

def strip(code):
    code = re.sub(r'/\*.*?\*/', '', code, flags=re.S)
    code = re.sub(r'//[^\n]*', '', code)
    code = re.sub(r'"(?:\\.|[^"\\])*"', '""', code)
    return code

def split_args(s):
    s = s.replace('->', '=#')   # a lambda arrow is not a closing angle bracket
    parts, depth, cur = [], 0, ''
    for ch in s:
        if ch in '(<[{': depth += 1
        elif ch in ')>]}': depth -= 1
        if ch == ',' and depth == 0:
            parts.append(cur); cur = ''
        else: cur += ch
    if cur.strip(): parts.append(cur)
    return [p for p in parts if p.strip()]

# 1. every project type with explicit method declarations: name -> {method: set(arities)}
types = {}
files = {}
for p in SRC.rglob('*.java'):
    raw = p.read_text(encoding='utf-8'); code = strip(raw)
    files[p] = code
    m = re.search(r'\b(?:public\s+)?(?:abstract\s+)?(?:final\s+)?(class|interface|record|enum)\s+(\w+)', code)
    if not m: continue
    name = m.group(2)
    methods = {}
    for d in re.finditer(r'(?m)^\s*(?:@\w+(?:\([^)]*\))?\s*)*(?:public|protected|default|static|private|abstract|final|\s)*[\w<>\[\],.? ]+?\s+(\w+)\s*\(([^)]*)\)\s*(?:throws [\w., ]+)?\s*[;{]', code):
        mname = d.group(1)
        if mname in ('if','for','while','switch','catch','return','new','super','this'): continue
        methods.setdefault(mname, set()).add(len(split_args(d.group(2))))
    # record components give accessors with 0 args
    rec = re.search(r'record\s+' + name + r'\s*\(([^)]*)\)', code)
    if rec:
        for comp in split_args(rec.group(1)):
            cn = comp.strip().split()[-1]
            methods.setdefault(cn, set()).add(0)
    types.setdefault(name, {}).update({k: types.get(name, {}).get(k, set()) | v for k, v in methods.items()})

CHECK = {n for n in types if re.search(r'(Service|Impl|Retry|Metrics|Limiter|Policy|Math|Rules|Identity|Retrying)$', n) or n in ('SettlementRules','BillMath')}  # *Properties are Lombok-generated: not checkable here
problems = []
for p, code in files.items():
    # receiver variables: fields and constructor/method parameters of checked types
    var_type = {}
    for f in re.finditer(r'\b(\w+)\s+(\w+)\s*[;=,)]', code):
        t, v = f.group(1), f.group(2)
        if t in CHECK: var_type.setdefault(v, t)
    # interface type for an Impl: calls go through the interface, so merge Impl methods under the interface name too
    for v, t in var_type.items():
        for call in re.finditer(r'(?<![\w.])' + re.escape(v) + r'\s*\.\s*(\w+)\s*\(', code):
            mname = call.group(1)
            # args by paren matching
            i = call.end(); depth = 1
            while i < len(code) and depth:
                depth += (code[i] == '(') - (code[i] == ')'); i += 1
            argc = len(split_args(code[call.end():i-1]))
            decl = types.get(t, {})
            if mname not in decl:
                # inherited from Object / Lombok / lambda-typed: ignore common ones
                if mname in ('equals','hashCode','toString','getClass'): continue
                problems.append(f'{p.relative_to(SRC)}: {v}.{mname}() - no such method on {t}')
            elif argc not in decl[mname]:
                problems.append(f'{p.relative_to(SRC)}: {v}.{mname}() called with {argc} args; {t} declares {sorted(decl[mname])}')
print('== Service/component call resolution (name and arity) ==')
for x in sorted(set(problems)): print('   [!]', x)
print(f'   {len(CHECK)} types checked;', 'every call resolves' if not problems else f'{len(set(problems))} problem(s)')
